class Table:
    def __init__(self, name, columns):
        self.name = name
        self.columns = columns
        self.rows = []

    def insert(self, values):
        self.rows.append(dict(zip(self.columns, values)))

    def select_all(self):
        return self.rows

    def select_where(self, col, value):
        return [r for r in self.rows if r.get(col) == value]

db = {}
db['users'] = Table('users', ['id', 'name', 'age'])
db['users'].insert([1, 'Alice', 30])
db['users'].insert([2, 'Bob', 25])
db['users'].insert([3, 'Charlie', 35])

for user in db['users'].select_all():
    print(f"{user['id']}: {user['name']} ({user['age']})")

print("\nUsers age 30:")
for user in db['users'].select_where('age', 30):
    print(f"  {user['name']}")
